  const hoverStoreRef = useRef<HoverPiecesStore | null>(null);
  if (!hoverStoreRef.current) hoverStoreRef.current = new HoverPiecesStore();
  const hoverStore = hoverStoreRef.current;

  useEffect(() => {
    const update = () => {
